INSERT INTO public.transport_hubs (id, name, name_bn, category, category_bn, location, upazila, description, connected_routes, facilities, operating_hours, phone_number, phone_numbers, banner_image)
VALUES (
  'santahar-railway-junction', 'Santahar Railway Junction', 'সান্তাহার রেলওয়ে জংশন', 'railway_junction',
  'প্রধান রেলওয়ে জংশন', 'Santahar Pouroshava, Adamdighi Upazila, Bogura 5850', 'আদমদীঘি', 'One of the most historic and largest dual-gauge railway junctions in Bangladesh. Situated in Bogura district, Santahar connects the broad-gauge western line (Khulna–Rajshahi–Parbatipur–Chilahati) with the eastern meter/dual gauge line leading to Bogura Sadar and Dhaka.',
  '["Santahar – Bogura – Dhaka","Santahar – Parbatipur – Chilahati – Panchagarh","Santahar – Natore – Ishwardi – Khulna","Santahar – Rajshahi","Santahar – Lalmonirhat – Burimari"]'::jsonb, '["5 large covered railway platforms with dual-gauge track","Multiple computerized ticket booking & e-ticket counters","Railway Hospital & medical emergency unit","Running staff rest house & VIP retiring rooms","Railway Police (GRP) station & security camp","Major locomotive fueling & maintenance yard","24/7 canteens, tea stalls & market"]'::jsonb, 'Open 24 hours (trains operating day and night)',
  '+880 1737-580578', '["+880 1737-580578","+880 741-62222","+880 741-62233","131"]'::jsonb, 'https://images.unsplash.com/photo-1541427468627-a89a96e5ca1d?auto=format&fit=crop&w=1200&q=80'
) ON CONFLICT (id) DO UPDATE SET
  phone_numbers = EXCLUDED.phone_numbers,
  banner_image = EXCLUDED.banner_image;

